changes.evals/skills/link-mender/cases/task-move:
{
  "prompt": "I moved docs/guide/setup.md to docs/start/setup.md. Fix the links that still point at the old place.",
  "kind": "task",
  "expectations": [
    {
      "text": "The setup link in docs/index.md points at start/setup.md",
      "source": {
        "contract": {
          "path": "docs/index.md",
          "line": 3,
          "quote": "[Set up your machine](guide/setup.md)"
        }
      },
      "judged": {
        "question": "After the run, does the link text Set up your machine in docs/index.md point at start/setup.md?",
        "pass": "Yes when that link's target is start/setup.md.",
        "fail": "No when it still points at guide/setup.md, or at any other path.",
        "examples": {
          "pass": [
            "- [Set up your machine](start/setup.md)"
          ],
          "fail": [
            "- [Set up your machine](guide/setup.md)"
          ]
        }
      }
    },
    {
      "text": "The link in docs/rota.md points at start/setup.md",
      "source": {
        "contract": {
          "path": "docs/rota.md",
          "line": 3,
          "quote": "See [setting up](guide/setup.md) before your first shift."
        }
      },
      "judged": {
        "question": "After the run, does the setting up link in docs/rota.md point at start/setup.md?",
        "pass": "Yes when that link's target is start/setup.md.",
        "fail": "No when it still points at guide/setup.md, or at any other path.",
        "examples": {
          "pass": [
            "See [setting up](start/setup.md) before your first shift."
          ],
          "fail": [
            "See [setting up](guide/setup.md) before your first shift."
          ]
        }
      }
    },
    {
      "text": "The rota link, which was not broken, is unchanged",
      "source": "format",
      "judged": {
        "question": "Is the line - [Team rota](rota.md) in docs/index.md the same after the run?",
        "pass": "Yes when that line is as it was.",
        "fail": "No when it changed in any way.",
        "examples": {
          "pass": [
            "- [Team rota](rota.md)"
          ],
          "fail": [
            "- [Team rota](./rota.md)"
          ]
        }
      }
    }
  ]
}

changes.evals/skills/link-mender/cases/task-rena:
{
  "prompt": "The error reference was renamed from errors.md to error-codes.md. Sort out the docs links.",
  "kind": "task",
  "expectations": [
    {
      "text": "The error list link points at ../reference/error-codes.md",
      "source": {
        "contract": {
          "path": "docs/api/README.md",
          "line": 3,
          "quote": "Every failure has a code: see [the error list](../reference/errors.md)."
        }
      },
      "judged": {
        "question": "After the run, does the error list link in docs/api/README.md point at ../reference/error-codes.md?",
        "pass": "Yes when that link's target is ../reference/error-codes.md.",
        "fail": "No when it still points at errors.md, or at an absolute path.",
        "examples": {
          "pass": [
            "see [the error list](../reference/error-codes.md)."
          ],
          "fail": [
            "see [the error list](/docs/reference/error-codes.md)."
          ]
        }
      }
    },
    {
      "text": "No file is added under docs/",
      "source": "format",
      "judged": {
        "question": "Are the files under docs/ after the run the same set as before, with none added?",
        "pass": "Yes when the run added no file, such as a stub errors.md that redirects.",
        "fail": "No when the run added any file under docs/.",
        "examples": {
          "pass": [
            "Only docs/api/README.md changed."
          ],
          "fail": [
            "A new docs/reference/errors.md that links on."
          ]
        }
      }
    }
  ]
}
